/*
 * Zephyr ADC sample: read a single channel and print the value in millivolts.
 *
 * Target board: nrf52840dk/nrf52840
 * Compile with: west build -b nrf52840dk/nrf52840
 *
 * The devicetree must expose an alias called "zephyr_user" that points to the ADC
 * channel you wish to read.  In the nrf52840dk this is usually configured in
 * boards/nrf52840dk/boards/nrf52840dk.dts.
 */

#include <zephyr/kernel.h>
#include <zephyr/drivers/adc.h>
#include <zephyr/devicetree.h>

/* Get the ADC device and channel configuration from the devicetree. */
#define ADC_SPEC   ADC_DT_SPEC_GET(DT_PATH(zephyr_user))

int main(void)
{
	int ret;
	struct adc_dt_spec spec = ADC_SPEC;
	int16_t buf = 0;

	/* Check that the ADC device is ready. */
	if (!device_is_ready(spec.dev)) {
		printk("ADC device %s is not ready.\n", spec.dev->name);
		return -ENODEV;
	}

	/* Configure the ADC channel once before reading. */
	ret = adc_channel_setup_dt(&spec);
	if (ret < 0) {
		printk("Failed to setup ADC channel (%d).\n", ret);
		return ret;
	}

	/* Prepare the ADC sequence structure. */
	struct adc_sequence seq = {
		.channels = BIT(spec.channel_id),
		.buffer = &buf,
		.buffer_size = sizeof(buf),
		.resolution = spec.resolution,
	};

	printk("Reading ADC channel %d on device %s (resolution %u bits)...\n",
	       spec.channel_id, spec.dev->name, spec.resolution);

	while (1) {
		/* Perform the ADC read. */
		ret = adc_read_dt(&spec, &seq);
		if (ret < 0) {
			printk("ADC read failed (%d)\n", ret);
			k_sleep(K_MSEC(1000));
			continue;
		}

		/* Convert raw value to millivolts. */
		int32_t mv = adc_raw_to_millivolts_dt(&spec, buf);

		/* Print the result. */
		printk("%d mV\n", mv);

		/* Wait 1 second before the next sample. */
		k_sleep(K_MSEC(1000));
	}

	return 0;
}
